function normalizeEntries(rawItems) {
  const flat = [];

  for (const item of rawItems) {
    const j = item.json;

    // Case 1: recursive Git Tree API body
    if (j && Array.isArray(j.tree)) {
      for (const t of j.tree) {
        if (!t.path || !t.path.startsWith('reports/')) continue;
        flat.push({
          path: t.path,
          type: t.type === 'tree' ? 'dir' : 'file',
        });
      }
      continue;
    }

    // Case 2: whole Contents array sitting in one item
    if (Array.isArray(j)) {
      for (const row of j) {
        if (!row || !row.name) continue;
        flat.push({
          path: row.path || ('reports/' + row.name),
          type: row.type === 'dir' || row.type === 'tree' ? 'dir' : 'file',
        });
      }
      continue;
    }

    // Case 3: normal n8n split items (one file/dir per item)
    if (j && j.name) {
      flat.push({
        path: j.path || ('reports/' + j.name),
        type: j.type === 'dir' || j.type === 'tree' ? 'dir' : 'file',
      });
    }
  }

  return flat;
}

function buildMarkdownTree(entries) {
  const lines = ['```text', 'reports/'];
  const byParent = {};

  for (const e of entries) {
    const parts = e.path.split('/');
    const parent = parts.length <= 2 ? 'reports' : parts.slice(0, -1).join('/');
    const name = parts[parts.length - 1];
    if (!byParent[parent]) byParent[parent] = [];
    byParent[parent].push({ name: name, type: e.type, path: e.path });
  }

  function walk(parentPath, depth) {
    const kids = byParent[parentPath] || [];
    kids.sort(function (a, b) {
      if (a.type !== b.type) return a.type === 'dir' ? -1 : 1;
      return a.name.localeCompare(b.name);
    });

    for (const kid of kids) {
      const indent = '  '.repeat(depth);
      lines.push(indent + kid.name + (kid.type === 'dir' ? '/' : ''));
      if (kid.type === 'dir') walk(kid.path, depth + 1);
    }
  }

  walk('reports', 1);
  lines.push('```');
  return lines.join('\n');
}

const entries = normalizeEntries($input.all());
entries.sort(function (a, b) {
  return a.path.localeCompare(b.path);
});

return [
  {
    json: {
      folderTreeMarkdown: buildMarkdownTree(entries),
      entryCount: entries.length,
      paths: entries.map(function (e) { return e.path; }),
    },
  },
];

const raw = $json.output;

const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;

if (!parsed.filename?.endsWith('.md')) {
  throw new Error('filename must end with .md');
}
if (!parsed.report_path?.startsWith('reports/')) {
  throw new Error('report_path must start with reports/');
}
if (parsed.report_path !== `${parsed.report_dir}/${parsed.filename}`) {
  throw new Error('report_path must equal report_dir/filename');
}

return {
  json: {
    filename: parsed.filename,
    report_dir: parsed.report_dir,
    report_path: parsed.report_path,
    create_dir: Boolean(parsed.create_dir),
    reason: parsed.reason,
  },
};
